	private void verifyProgramStateThenUndo(bool functionShouldExist) {

		waitForBusyTool(tool);

		// verify that function does not get created when resumed
		cb.goToField(addr("0x1001100"), "Operands", 0, 0);
		Function f = program.getListing().getFunctionAt(addr("0x100110a"));
		if (functionShouldExist) {
			assertNotNull("Function should have been analyzed", f);
		}
		else {
			assertNull("Function should not have been analyzed", f);
		}

		Options list = program.getOptions("TEST");
		assertTrue("Lower priorty analysis task failed to complete after worker",
			list.getBoolean("p1", false));

		try {
			program.undo();
		}
		catch (IOException e) {
			Assert.fail("Unexpected exception");
		}
	}

	private void schedule(AutoAnalysisManager mgr, BackgroundCommand<Program> cmd, int priority) {
		invokeInstanceMethod("schedule", mgr, new Class[] { typeof(BackgroundCommand), typeof(int) },
			new object[] { cmd, priority });
	}

	private static class SetTestPropertyCommand : BackgroundCommand<Program> {
		private string property;
		private long delay;

		SetTestPropertyCommand(string property, long delay) : base("SetTestProperty", false, false, false)
    {
			this.property = property;
			this.delay = delay;
		}

		/* @Override */
		public bool applyTo(Program p, TaskMonitor monitor) {
			try {
				Thread.sleep(delay);
			}
			catch (InterruptedException e) {
				Assert.fail();// should never happen
			}

			Options list = p.getOptions("TEST");
			list.setBoolean(property, true);
			return true;
		}
	}

	private class WorkerBackgroundTestCmd : BackgroundCommand<Program> {

		private bool analyzeChanges;
		private volatile bool isFinished = false;
		private Exception error;

		WorkerBackgroundTestCmd(bool analyzeChanges) : base("WorkerBackgroundCmd", false, true, false)
    {
			this.analyzeChanges = analyzeChanges;
		}

		/* @Override */
		public bool applyTo(Program p, TaskMonitor monitor) {
			AutoAnalysisManager mgr = AutoAnalysisManager.getAnalysisManager(p);
			try {
				return mgr.scheduleWorker(worker, null, analyzeChanges, TaskMonitor.DUMMY);
			}
			catch (Exception e) {
				error = e;
			}
			finally {
				lock (this) {
					isFinished = true;
					notifyAll();
				}
			}
			return false;
		}

		void waitUntilFinished() {
			if (!isFinished) {
				try {
					wait();
				}
				catch (InterruptedException e) {
					// ignore
				}
			}
		}
	}


	internal class _Anon_AnalysisWorker_1 : AnalysisWorker
	{


		/* @Override */
		public string getWorkerName() {
			return "testAutoAnalyzeDisableResume";
		}

		/* @Override */
		public bool analysisWorkerCallback(Program p, object workerContext,
				TaskMonitor monitor) {

			// Can't invoke action since we are in background task here

			Options list = p.getOptions("TEST");
			assertTrue("Higher priorty analysis task failed to run first",
				list.getBoolean("p0", false));
			assertTrue("Lower priorty analysis task failed to run last",
				!list.getBoolean("p1", false));

			cb.goToField(addr("0x1001100"), "Operands", 0, 0);
			assertNull(p.getListing().getFunctionAt(addr("0x100110a")));

			DisassembleCommand cmd = new DisassembleCommand(addr("0x1001100"), null, true);
			cmd.applyTo(p, monitor);

			return true;
		}
	
	}


